""" Common utility functions for the project """
import os
import re
import subprocess
import paramiko
from datetime import datetime
from constants import *

def ssh_connection_check(client):
    # Check if the SSH connection is active
    if client.get_transport() is not None:
        print("SSH connection is active.")
        stdin, stdout, stderr = client.exec_command(Xb_UPTIME_VERSION)
        output = stdout.read().decode('utf-8')
        print(f"Uptime : {output}")
    else:
        print("SSH connection is not active. Exiting...")
        exit()

def ssh_connect(host, user, password):
    # Establish SSH connection to the RDK-B device
    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    client.connect(host, username=user, password=password)
    return client

def parse_dmcli_output(output):
    """ Parse the dmcli output and extract the value """
    match = re.search(r'value:\s*(\S+)', output)
    if match:
        return match.group(1)
    return None

def run_dmcli_command(command, timeout=TIMEOUT):
    """ Run a dmcli command and return the output"""
    result = subprocess.run(
        command,
        shell=True,
        check=False,
        capture_output=True,
        text=True,
        timeout=timeout
    )
    return result.stdout.strip()

def extract_rownum(text, delimiter):
    """ Extract the row numbers from the text based on the delimiter """
    rows = text.split(delimiter)
    row_numbers = []
    for row in rows:
        match = re.search(r'(\d+)', row)
        if match:
            row_numbers.append(int(match.group(1)))
    return row_numbers

def parse_test_step(docstring):
    """Parse test step information from docstring.
    Returns a list of all test steps found in the docstring."""
    # Remove leading/trailing whitespace from each line and join
    cleaned_docstring = '\n'.join(line.strip() for line in docstring.split('\n'))

    # Find all test step sections
    step_pattern = r'<TEST_STEP>\s*(\d+)\s*</TEST_STEP>\s*<TEST_STEP_DESCRIPTION>\s*(.*?)\s*</TEST_STEP_DESCRIPTION>'
    step_matches = list(re.finditer(step_pattern, cleaned_docstring, re.DOTALL))

    if not step_matches:
        return None

    # Extract all test steps
    test_steps = []
    for match in step_matches:
        step_info = {
            'step': match.group(1),
            'details': match.group(2).strip()
        }
        test_steps.append(step_info)

    print(f"Found {len(test_steps)} test steps in docstring: {[s['step'] for s in test_steps]}")
    return test_steps

def update_html_report(report_path, test_steps, statuses):
    """Update HTML report with test steps and their status."""
    # Create initial report if it doesn't exist
    if not os.path.exists(report_path):
        os.makedirs(os.path.dirname(report_path), exist_ok=True)
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        initial_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Test Report</title>
    <style>
        body {{
            font-family: sans-serif;
        }}
        .header {{
            text-align: center;
            margin-bottom: 20px;
        }}
        table {{
            width: 80%;
            margin: 20px auto;
            border-collapse: collapse;
        }}
        th, td {{
            border: 1px solid #ddd;
            padding: 8px;
            text-align: left;
        }}
        th {{
            background-color: #f2f2f2;
            font-weight: bold;
        }}
        tr:nth-child(even) {{background-color: #f9f9f9;}}
        .pass {{ color: green; }}
        .fail {{ color: red; }}
        .error {{ color: orange; }}
    </style>
</head>
<body>
    <div class='header'>
        <h1>Test Report - {timestamp}</h1>
        <h2>Test ID: TC_XB_SPEEDTEST_1001</h2>
        <h2>Test Case Name: - Test case for speedtest from cli</h2>
        <h2>Test Case Description: - To verify the speedtest from cli</h2>
    </div>
    <table>
        <tr><th>Test Step</th><th>Details</th><th>Status</th></tr>
    </table>
</body>
</html>"""
        with open(report_path, 'w') as f:
            f.write(initial_content)

    # Read current content
    with open(report_path, 'r') as f:
        content = f.read()

    # Find the table in the HTML
    table_match = re.search(r'<table>.*?</table>', content, re.DOTALL)
    if not table_match:
        return

    # Create new table rows, sorting by step number
    new_rows = ['<tr><th>Test Step</th><th>Details</th><th>Status</th></tr>']
    sorted_steps = sorted(test_steps, key=lambda x: int(x['step']))

    for step in sorted_steps:
        status = statuses.get(str(step['step']), 'Not Executed')
        status_class = 'pass' if status.lower() == 'passed' else 'fail' if status.lower() == 'failed' else 'error'
        # Format step details to preserve newlines
        details = step['details'].replace('\n', '<br/>')
        row = f'<tr><td>{step["step"]}</td><td>{details}</td><td class="{status_class}">{status}</td></tr>'
        new_rows.append(row)

    # Replace old table with new one
    new_table = '<table>\n' + '\n'.join(new_rows) + '\n</table>'
    updated_content = re.sub(r'<table>.*?</table>', new_table, content, flags=re.DOTALL)

    with open(report_path, 'w') as f:
        f.write(updated_content)

def run_speedtest(ssh_connection=None):
    """Runs speedtest, optionally over SSH.

    Args:
        ssh_connection: A paramiko SSHClient object, or None for local execution.

    Returns:
        A dictionary containing speedtest results, or None on error.
    """
    try:
        if ssh_connection:  # Run over SSH
            command = "speedtest"
            stdin, stdout, stderr = ssh_connection.exec_command(command)
            output = stdout.read().decode('utf-8')  # Decode the output
            error = stderr.read().decode('utf-8')
            print (f"Output : {output}")
            print (f"Error : {error}")
            if error: #check for errors from the remote
                print(f"Error on remote: {error}")
                return None
        else:  # Run locally
            result = subprocess.run(["speedtest"], capture_output=True, text=True, check=True)
            output = result.stdout

        # Parse the output (same parsing logic as before)
        download_match = re.search(r"Download: (\d+\.\d+) Mbit/s", output)
        upload_match = re.search(r"Upload: (\d+\.\d+) Mbit/s", output)
        host_match = re.search(r"Hosted by (.+) \[(.+?) km\]", output)
        ping_match = re.search(r"(\d+\.\d+) ms", output)

        if download_match and upload_match and host_match and ping_match:
            download_speed = download_match.group(1)
            upload_speed = upload_match.group(1)
            host = host_match.group(1)
            ping = ping_match.group(1)

            return {
                "download": download_speed,
                "upload": upload_speed,
                "host": host,
                "ping": ping
            }
        else:
            print("Error: Could not parse speedtest output.")
            print(output)  # Print for debugging
            return None

    except subprocess.CalledProcessError as e:
        print(f"Error: speedtest command failed locally: {e}")
        return None
    except FileNotFoundError:
        print("Error: speedtest command not found locally. Make sure it's installed and in your PATH.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

def format_speedtest_output(speedtest_data):
  """Formats the speedtest data into a user-friendly string.

  Args:
    speedtest_data: A dictionary containing speedtest results, as returned by run_speedtest().

  Returns:
    A formatted string with the speedtest results, or None if the input is invalid.
  """
  if not speedtest_data:
    return None

  return (
      f"Testing download speed - {speedtest_data['download']} Mbit/s\n"
      f"Testing upload speed -  {speedtest_data['upload']} Mbit/s\n"
      f"Host : {speedtest_data['host']}\n"
      f"Ping : {speedtest_data['ping']} ms"
  )

