#!/usr/bin/python3

import argparse
import subprocess
import json
import re
import signal
import sys
from constants import *
from common_utils import *

def create_response():
    return {
        "status": "failure",
        "error_message": "",
        "response_code": 1,
        "spoken_response": "",
        "output": ""
    }

def get_mac_address_by_hostname(hostname):
    """ Get the MAC address of a connected client by hostname """
    try:
        num = run_dmcli_command(f"{DM_RETV} {DM_HOST_NUMBER_OF_ENTRIES}")

        if num is None:
            raise ValueError("Failed to get the number of host entries")

        num = int(num)

        for i in range(1, num + 1):
            command = f"dmcli eRT retv Device.Hosts.Host.{i}.HostName"
            current_hostname = run_dmcli_command(command)
            if current_hostname == hostname:
                command = f"dmcli eRT retv Device.Hosts.Host.{i}.PhysAddress"
                mac_address = run_dmcli_command(command)
                return mac_address

        raise ValueError(f"Hostname {hostname} not found")
    except (subprocess.CalledProcessError, ValueError) as e:
        print(f"Error: {e}")
        return 1

def get_pc_row_numbers():
    """ Get the specific row numbers of managed devices. Returns a list of row numbers """
    try:
        command = f"dmcli eRT getv {DM_PC}. | grep -i Description"
        output = run_dmcli_command(command)
        row_numbers = extract_rownum(output, DM_PC)
        return row_numbers
    except subprocess.CalledProcessError as e:
        print(f"Error executing dmcli command: {e.stderr.decode()}")
        return None

def get_row_number_by_hostname(hostname):
    """ Get the row number of a managed device based on the hostname """
    try:
        row_numbers = get_pc_row_numbers()

        for i in row_numbers:
            command = f"dmcli eRT retv {DM_PC}.{i}.Description"
            current_hostname = run_dmcli_command(command)
            if current_hostname == hostname:
                return i

        raise ValueError(f"Hostname {hostname} not found in ManagedDevices.Device table")
    except (subprocess.CalledProcessError, ValueError) as e:
        print(f"Error: {e}")
        return None

def enable_disable_pc(enable):
    """ Enable or Disable Parental Control Managed Devices Feature """
    response = create_response()
    command = f"dmcli eRT setv {DM_MD}.Enable bool {enable}"
    try:
        output = run_dmcli_command(command)
        response = {
            "status": "success" if DM_SUCCESS in output else "failure",
            "error_message": "" if DM_SUCCESS in output else "Failed to set Enable value",
            "response_code": 0 if DM_SUCCESS in output else 1,
            "spoken_response": "",
            "output": "",
        }
        return response
    except subprocess.CalledProcessError as e:
        response = {
            "status": "failure",
            "error_message": e.stderr.decode(),
            "response_code": 1,
            "spoken_response": "",
            "output": "",
        }
        return response

def block_device(hostname, start_time, end_time, block_days, always_block):
    """ Block a new device """
    response = create_response()
    try:
        mac_address = get_mac_address_by_hostname(hostname)
        if mac_address is None:
            raise ValueError(f"MAC address for hostname {hostname} not found")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    try:
        # Add a new row to the ManagedDevices table
        command = f"dmcli eRT addtable {DM_PC}."
        output = run_dmcli_command(command)
        print(output)
        if DM_SUCCESS not in output:
            raise ValueError("Failed to add a new row to the ManagedDevices table")

        row_numbers = extract_rownum(output, DM_PC)
        print(row_numbers)
        if not row_numbers:
            raise ValueError("Failed to extract row number")
        row_number = row_numbers[-1]
        print(row_number)
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

    try:
        # Set the common parameters for the blocked device
        common_commands = [
            f"dmcli eRT setv {DM_MD}.Enable bool true",
            f"dmcli eRT setv {DM_PC}.{row_number}.Description string {hostname}",
            f"dmcli eRT setv {DM_PC}.{row_number}.MACAddress string {mac_address}"
        ]

        for cmd in common_commands:
            output = run_dmcli_command(cmd)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to execute command: {cmd}")

        # Set the specific parameters based on always_block
        if always_block:
            specific_commands = [
                f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool true"
            ]
        else:
            if block_days:
                block_days = block_days.strip() or "Mon,Tue,Wed,Thu,Fri,Sat,Sun" # Default is all days

            specific_commands = [
                f"dmcli eRT setv {DM_PC}.{row_number}.Type string Block",
                f"dmcli eRT setv {DM_PC}.{row_number}.StartTime string {start_time}",
                f"dmcli eRT setv {DM_PC}.{row_number}.EndTime string {end_time}",
                f"dmcli eRT setv {DM_PC}.{row_number}.BlockDays string {block_days}"
            ]

        for cmd in specific_commands:
            output = run_dmcli_command(cmd)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to execute command: {cmd}")

        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = "Device blocked successfully"
        return response
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

def unblock_device(hostname):
    """ Unblock a device from block list """
    response = create_response()
    try:
        row_number = get_row_number_by_hostname(hostname)
        if row_number is None:
            raise ValueError(f"Hostname {hostname} not found in ManagedDevices.Device table")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    # Unblock the device by setting the Type to Allow
    command = f"dmcli eRT setv {DM_PC}.{row_number}.Type string Allow" 
    output = run_dmcli_command(command)
    if DM_SUCCESS in output:
        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = f"Device {hostname} unblocked successfully"
    else:
        response["error_message"] = f"Failed to unblock the device {hostname}"

    return response

def delete_device(hostname):
    """ Delete a blocked device from the ManagedDevices table """
    response = create_response()
    try:
        row_number = get_row_number_by_hostname(hostname)
        if row_number is None:
            raise ValueError(f"Hostname {hostname} not found in ManagedDevices.Device table")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    # Delete the row from the ManagedDevices table
    command = f"dmcli eRT deltable {DM_PC}.{row_number}."
    output = run_dmcli_command(command)
    if DM_SUCCESS in output:
        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = f"Device {hostname} deleted successfully from the block list"
    else:
        response["error_message"] = f"Failed to delete the device {hostname} from the block list"

    return response

def list_blocked_devices():
    """ List all the devices that are blocked """
    response = create_response()
    try:
        row_numbers = get_pc_row_numbers()
        if row_numbers is None:
            raise ValueError("Failed to get Parental control rows")

        blocked_devices = []
        for i in row_numbers:
            command = f"dmcli eRT retv {DM_PC}.{i}.Type"
            output = run_dmcli_command(command)

            if "Block" in output:
                command = f"dmcli eRT retv {DM_PC}.{i}.Description"
                hostname = run_dmcli_command(command)
                blocked_devices.append(hostname)

        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = "Blocked devices listed successfully"
        response["output"] = blocked_devices
        return response
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

def update_device(hostname, start_time, end_time, block_days, always_block):
    """ Update the block time/day for a device """
    response = create_response()
    try:
        row_number = get_row_number_by_hostname(hostname)
        if row_number is None:
            raise ValueError(f"Hostname {hostname} not found in ManagedDevices.Device table")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    try:
        if always_block:
            command = f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool true"
            output = run_dmcli_command(command)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to set AlwaysBlock for {hostname}")
        else:
            command = command = f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool false"
            output = run_dmcli_command(command)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to set BlockDays for {hostname}")

            if start_time:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.StartTime string {start_time}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set StartTime for {hostname}")

            if end_time:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.EndTime string {end_time}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set EndTime for {hostname}")

            if block_days:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.BlockDays string {block_days}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set BlockDays for {hostname}")

        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = "Device block time updated successfully."
        return response
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

def handle_sigterm(signum, frame):
    print("Received SIGTERM, exiting gracefully...")
    sys.exit(0)

def validate_time_format(time_str):
    """ Validate time format to be between 00:00 and 23:59 """
    if re.match(r"^([01]\d|2[0-3]):([0-5]\d)$", time_str):
        return True
    return False

def parental_control_settings():
    """
    TODO: Update as per the JIRA ticket
    1. Enable or Disable Parental Control Managed Devices Feature --Enable true or false
    2. Block a device
    3. Unblock/Delete a device from block list - Find row number and delete
    4. List all the devices that are blocked - Get from Hosts table and loop over PC table
    5. Update the block time/day for a device - Find row number and update
    """
    # TODO: Declare Spoken response and dmcli constants
    response = create_response()

    signal.signal(signal.SIGTERM, handle_sigterm)
    parser = argparse.ArgumentParser(description="Parental Control Managed Devices")
    parser.add_argument('--Enable', type=bool, help='Enable or Disable the Managed Devices Feature: true or false')
    parser.add_argument('--Hostname', type=str, help='Enter the Hostname for the managed device: Test_iPhone')
    parser.add_argument('--StartTime', type=str, help='Enter the Start Time (UTC Format) to block the managed device: 22:15')
    parser.add_argument('--EndTime', type=str, help='Enter the End Time (UTC Format) to unblock the managed device: 23:00')
    parser.add_argument('--BlockDays', type=str, help='Block days for parental control') # Mon,Tue,Wed,Thu,Fri,Sat,Sun If not specified, default is all days
    parser.add_argument('--AlwaysBlock', type=bool, help='Block the device completely: true or false')
    parser.add_argument('--a', type=str, required=True, choices=['enable', 'disable', 'list', 'block', 'unblock', 'delete', 'update'], help='Action to perform')

    args = parser.parse_args()
    if args.a == 'enable':
        response = enable_disable_pc(True)
    elif args.a == 'disable':
        response = enable_disable_pc(False)
    elif args.a == 'list':
        response = list_blocked_devices()
    elif args.a == 'block':
        if args.Hostname and (args.AlwaysBlock or (args.StartTime and args.EndTime and 
                                                   validate_time_format(args.StartTime) and validate_time_format(args.EndTime))):
            response = block_device(args.Hostname, args.StartTime, args.EndTime, args.BlockDays, args.AlwaysBlock)
        else:
            response["response_code"] = 1
            response["error_message"] = (
                "Hostname is mandatory, either AlwaysBlock should be present or "
                "StartTime and EndTime should be specified."
                "Format for StartTime and EndTime should be in 24-hour format (HH:MM)"
            )
    elif args.a == 'unblock':
        if args.Hostname:
            response = unblock_device(args.Hostname)
        else:
            response["response_code"] = 1
            response["error_message"] = "Hostname is required for unblocking a device"
    elif args.a == 'delete': 
        if args.Hostname:
            response = delete_device(args.Hostname) #Delete from ManagedDevices table
        else:
            response["response_code"] = 1
            response["error_message"] = "Hostname is required for deleting a device from Blocked list"
    elif args.a == 'update':
        if args.Hostname and (args.AlwaysBlock or ((args.StartTime or args.EndTime) and 
                                                   (validate_time_format(args.StartTime) or validate_time_format(args.EndTime)))):
            response = update_device(args.Hostname, args.StartTime, args.EndTime, args.BlockDays, args.AlwaysBlock)
        else:
            response["response_code"] = 1
            response["error_message"] = (
                "Hostname is mandatory, either AlwaysBlock should be present or "
                "StartTime and EndTime should be specified."
                "Format for StartTime and EndTime should be in 24-hour format (HH:MM)"
            )
    else:
        response["response_code"] = 1
        response["error_message"] = "Invalid arguments provided. Please check the usage."

    print(json.dumps(response))

    sys.exit(response["response_code"])

if __name__ == "__main__":
    parental_control_settings()

