def block_device(hostname, start_time, end_time, block_days, always_block):
    """ Block a new device """
    response = create_response()
    try:
        mac_address = get_mac_address_by_hostname(hostname)
        if mac_address is None:
            raise ValueError(f"MAC address for hostname {hostname} not found")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    try:
        # Add a new row to the ManagedDevices table
        command = f"dmcli eRT addtable {DM_PC}."
        output = run_dmcli_command(command)
        print(output)
        if DM_SUCCESS not in output:
            raise ValueError("Failed to add a new row to the ManagedDevices table")

        row_numbers = extract_rownum(output, DM_PC)
        print(row_numbers)
        if not row_numbers:
            raise ValueError("Failed to extract row number")
        row_number = row_numbers[-1]
        print(row_number)
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

    try:
        # Set the common parameters for the blocked device
        common_commands = [
            f"dmcli eRT setv {DM_MD}.Enable bool true",
            f"dmcli eRT setv {DM_PC}.{row_number}.Description string {hostname}",
            f"dmcli eRT setv {DM_PC}.{row_number}.MACAddress string {mac_address}"
        ]

        for cmd in common_commands:
            output = run_dmcli_command(cmd)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to execute command: {cmd}")

        # Set the specific parameters based on always_block
        if always_block:
            specific_commands = [
                f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool true"
            ]
        else:
            if block_days:
                block_days = block_days.strip() or "Mon,Tue,Wed,Thu,Fri,Sat,Sun" # Default is all days

            specific_commands = [
                f"dmcli eRT setv {DM_PC}.{row_number}.Type string Block",
                f"dmcli eRT setv {DM_PC}.{row_number}.StartTime string {start_time}",
                f"dmcli eRT setv {DM_PC}.{row_number}.EndTime string {end_time}",
                f"dmcli eRT setv {DM_PC}.{row_number}.BlockDays string {block_days}"
            ]

        for cmd in specific_commands:
            output = run_dmcli_command(cmd)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to execute command: {cmd}")

        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = "Device blocked successfully"
        return response
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

