def update_device(hostname, start_time, end_time, block_days, always_block):
    """ Update the block time/day for a device """
    response = create_response()
    try:
        row_number = get_row_number_by_hostname(hostname)
        if row_number is None:
            raise ValueError(f"Hostname {hostname} not found in ManagedDevices.Device table")
    except ValueError as e:
        response["error_message"] = str(e)
        return response

    try:
        if always_block:
            command = f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool true"
            output = run_dmcli_command(command)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to set AlwaysBlock for {hostname}")
        else:
            command = command = f"dmcli eRT setv {DM_PC}.{row_number}.AlwaysBlock bool false"
            output = run_dmcli_command(command)
            if DM_SUCCESS not in output:
                raise ValueError(f"Failed to set BlockDays for {hostname}")

            if start_time:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.StartTime string {start_time}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set StartTime for {hostname}")

            if end_time:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.EndTime string {end_time}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set EndTime for {hostname}")

            if block_days:
                command = f"dmcli eRT setv {DM_PC}.{row_number}.BlockDays string {block_days}"
                output = run_dmcli_command(command)
                if DM_SUCCESS not in output:
                    raise ValueError(f"Failed to set BlockDays for {hostname}")

        response["status"] = "success"
        response["response_code"] = 0
        response["spoken_response"] = "Device block time updated successfully."
        return response
    except (subprocess.CalledProcessError, ValueError) as e:
        response["error_message"] = str(e)
        return response

