def run_tests(tests_to_run):
    """Runs the specified tests."""
    suite = unittest.TestSuite()

    for test_module_name in tests_to_run:
        print(f"Trying to import: {test_module_name}")
        try:
            test_module = __import__(test_module_name, fromlist=["*"])  # Import everything

            print(f"Imported: {test_module_name}")

            # Dynamically find all test classes
            for name in dir(test_module):
                obj = getattr(test_module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase):
                    print(f"Adding tests from: {obj.__name__}")  # Use obj.__name__
                    suite.addTest(unittest.TestLoader().loadTestsFromModule(test_module)) # Load from module

        except ImportError as e:
            print(f"ImportError: {e}")
            print(f"sys.path: {sys.path}")
            return None
        except Exception as e:
            print(f"Error running tests from '{test_module_name}': {e}")
            return None

    # Create a custom test runner to capture step statuses
    class StepStatusRunner(unittest.TextTestRunner):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.step_statuses = {}
            self._current_test = None
            self._output_buffer = []

        def _makeResult(self):
            class OutputCaptureResult(unittest.TextTestResult):
                def __init__(self, *args, **kwargs):
                    super().__init__(*args, **kwargs)
                    self.step_statuses = {}
                    self._output_buffer = []
                    self._current_test = None

                def startTest(self, test):
                    self._output_buffer = []
                    self._current_test = test
                    super().startTest(test)

                def addSuccess(self, test):
                    self._processOutput()
                    super().addSuccess(test)

                def addError(self, test, err):
                    self._processOutput()
                    super().addError(test, err)

                def addFailure(self, test, err):
                    self._processOutput()
                    super().addFailure(test, err)

                def _processOutput(self):
                    if not self._current_test:
                        return
                    output = ''.join(self._output_buffer)
                    for line in output.splitlines():
                        if "Test step" in line and "status:" in line:
                            try:
                                step_num = line.split("Test step")[1].split(":")[0].strip()
                                step_status = line.split("status:")[1].strip().lower()
                                self.step_statuses[f"{self._current_test._testMethodName}_{step_num}"] = step_status
                            except:
                                continue
                    self._output_buffer = []

                def addOutput(self, output):
                    if self._current_test:
                        self._output_buffer.append(output)
                        self._processOutput()

            result = OutputCaptureResult(self.stream, self.descriptions, self.verbosity)
            result.step_statuses = self.step_statuses
            return result

        def _processOutput(self, test):
            for line in self._output_buffer:
                if "Test step" in line and "status:" in line:
                    try:
                        step_num = line.split("Test step")[1].split(":")[0].strip()
                        step_status = line.split("status:")[1].strip().lower()
                        self.step_statuses[f"{test._testMethodName}_{step_num}"] = step_status
                    except:
                        continue
            self._output_buffer = []

        def _addError(self, test, err):
            self._processOutput(test)
            unittest.TextTestResult.addError(self, test, err)

        def _addFailure(self, test, err):
            self._processOutput(test)
            unittest.TextTestResult.addFailure(self, test, err)

        def _addSuccess(self, test):
            self._processOutput(test)
            unittest.TextTestResult.addSuccess(self, test)

    runner = StepStatusRunner(stream=sys.stdout)
    result = runner.run(suite)
    return result

